import "./badge.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type BadgeTone = "default" | "accent" | "success" | "warning" | "danger";

export type BadgeProps = ComponentProps<"span"> & {
  tone?: BadgeTone | undefined;
};

export function Badge({ tone = "default", className, ...rest }: BadgeProps) {
  return (
    <span className={cx("ns-badge", className)} data-tone={tone} {...rest} />
  );
}

@layer components {
  .ns-badge {
    display: inline-flex;
    align-items: center;
    gap: var(--space-1, 0.25rem);
    padding: var(--space-1, 0.25rem) var(--space-3, 0.39rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: 999px;
    font: inherit;
    font-size: var(--type-xs, 0.64rem);
    font-weight: var(--weight-medium, 500);
    line-height: var(--leading-tight, 1.25);
    letter-spacing: 0.02em;
    color: var(--text-sub, #5c5c5c);
    background: none;
    box-shadow: var(--flat);
  }

  .ns-badge[data-tone="accent"] {
    color: var(--key-line, #221898);
    border-color: var(--accent-line, color-mix(in srgb, var(--key-line, #221898) 35%, transparent));
    background: var(--accent-surface, color-mix(in srgb, var(--key, #a2c7ff) 18%, transparent));
  }

  .ns-badge[data-tone="success"] {
    color: var(--success, #2f6b3a);
    border-color: var(--success-line, color-mix(in srgb, var(--success, #2f6b3a) 35%, transparent));
    background: var(--success-surface, color-mix(in srgb, var(--success, #2f6b3a) 10%, transparent));
  }

  .ns-badge[data-tone="warning"] {
    color: var(--warning, #8a5a12);
    border-color: var(--warning-line, color-mix(in srgb, var(--warning, #8a5a12) 35%, transparent));
    background: var(--warning-surface, color-mix(in srgb, var(--warning, #8a5a12) 10%, transparent));
  }

  .ns-badge[data-tone="danger"] {
    color: var(--error, #8f3232);
    border-color: var(--error-line, color-mix(in srgb, var(--error, #8f3232) 35%, transparent));
    background: var(--error-surface, color-mix(in srgb, var(--error, #8f3232) 10%, transparent));
  }
}
